// Fase 5 (Monte o seu bot) — PAINEL
// Uso: coloque este arquivo na pasta do projeto e rode:  node instalar-fase5-painel.cjs
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const raiz = process.cwd();
if (!fs.existsSync(path.join(raiz, 'src', 'app')) || !fs.existsSync(path.join(raiz, 'package.json'))) {
  console.error('❌ Rode este comando dentro da pasta do PAINEL (onde ficam package.json e src/app).');
  process.exit(1);
}
const arquivos = JSON.parse(zlib.gunzipSync(Buffer.from(DADOS(), 'base64')).toString('utf8'));
let n = 0;
for (const [rel, conteudo] of Object.entries(arquivos)) {
  const destino = path.join(raiz, ...rel.split('/'));
  fs.mkdirSync(path.dirname(destino), { recursive: true });
  const existia = fs.existsSync(destino);
  fs.writeFileSync(destino, conteudo);
  console.log((existia ? '  atualizado  ' : '  criado      ') + rel);
  n++;
}
// adiciona os scripts predev/prebuild no package.json sem mexer no resto
const pkgPath = path.join(raiz, 'package.json');
const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
const scripts = {};
for (const [k, v] of Object.entries(pkg.scripts || {})) {
  if (k === 'predev' || k === 'prebuild') continue;
  if (k === 'dev') scripts.predev = 'node scripts/gerar-template-bot.mjs';
  if (k === 'build') scripts.prebuild = 'node scripts/gerar-template-bot.mjs';
  scripts[k] = v;
}
pkg.scripts = scripts;
fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
console.log('  ajustado     package.json (scripts predev e prebuild)');
console.log('\n✅ ' + n + ' arquivos prontos. Pode apagar o instalar-fase5-painel.cjs.');
function DADOS() { return ''; }
